mapper.select:
select portfolioId, portfolioName, acctNo, acctName, ccy, acctType, cdate, cashBalance, tradeCash, cashAvailable, desirableCash, preReductionCash, advanceCash, adjustmentAmount from ( select portfolioId, portfolioName, acctNo, acctName, ccy, acctType, cdate, cashBalance, tradeCash, cashAvailable, (case when acctType = 'A07' and retrievalDesirableCash > 0 then cashBalance else tradeCash end) as desirableCash, (case when acctType = 'A07' and retrievalDesirableCash > 0 then 0 else cashBalance - tradeCash end) as preReductionCash, advanceCash, adjustmentAmount from (select portfolioId, portfolioName, acctNo, acctName, ccy, acctType, cdate,
(case when CASH_FLOW_AMOUNT99 is not null then CASH_AMOUNT03 + CASH_FLOW_AMOUNT99 else CASH_AMOUNT03 end) as cashBalance,
(case when CASH_FLOW_AMOUNT99 is not null then CASH_FLOW_AMOUNT01 + CASH_AMOUNT03 + CASH_AMOUNT07 + CASH_AMOUNT08 + CASH_FLOW_AMOUNT99 else CASH_FLOW_AMOUNT01 + CASH_AMOUNT03 + CASH_AMOUNT07 + CASH_AMOUNT08 end) as tradeCash,
(case when CASH_FLOW_AMOUNT99 is not null then ETR_AMOUNTE01 + ETR_AMOUNTE02 + CASH_FLOW_AMOUNT99 else ETR_AMOUNTE01 + ETR_AMOUNTE02 end) as cashAvailable, ETR_AMOUNTE02 as advanceCash, (CASH_FLOW_AMOUNT01 + CASH_AMOUNT07) as retrievalDesirableCash, CASH_FLOW_AMOUNT99 as adjustmentAmount from ( select portfolioId, portfolioName, acctNo, acctName, t.ccy as ccy, acctType, cdate, IFNULL(CASH_AMOUNT03,0) as CASH_AMOUNT03, IFNULL(CASH_AMOUNT07,0) as CASH_AMOUNT07, IFNULL(CASH_AMOUNT08,0) as CASH_AMOUNT08, IFNULL(CASH_FLOW_AMOUNT01,0) as CASH_FLOW_AMOUNT01, IFNULL(CASH_FLOW_AMOUNT99,0) as CASH_FLOW_AMOUNT99, IFNULL(ETR_AMOUNTE01,0) as ETR_AMOUNTE01, IFNULL(ETR_AMOUNTE02,0) as ETR_AMOUNTE02 from ( select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, t2.acct_no as acctNo, t2.acct_name as acctName, t2.ccy as ccy, t1.acct_type as acctType,
STR_TO_DATE(#{cdate},'%Y-%m-%d') as cdate from PTL_PORTFOLIO t INNER JOIN PTL_CAPACCT_INFO t1 on t1.portfolio_id = t.portfolio_id INNER JOIN STL_CAPACCT_INFO t2 on t2.acct_no = t1.acct_no where t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}
and t2.acct_no = #{acctNo,jdbcType=VARCHAR}
group by t.portfolio_id, t.portfolio_name, t2.acct_no, t2.acct_name, t2.ccy, t1.acct_type ) t left join ( select portfolio_id, acct_id, ccy, IFNULL(sum(case when hoding_type = '03' then AMOUNT end),0) CASH_AMOUNT03, IFNULL(sum(case when hoding_type = '07' then AMOUNT end),0) CASH_AMOUNT07, IFNULL(sum(case when hoding_type = '08' then AMOUNT end),0) CASH_AMOUNT08 from PTL_CASH_POSITION where cdate = STR_TO_DATE(#{cdate},'%Y-%m-%d')
#{ptlHodingType,jdbcType=VARCHAR}
group by portfolio_id, acct_id, ccy ) t3 on t3.portfolio_id = t.portfolioId and t3.acct_id = t.acctNo and t3.ccy = t.ccy left join ( select portfolio_id, acct_id, ccy, IFNULL(sum(case when hoding_type = '01' then AMOUNT end),0) CASH_FLOW_AMOUNT01, IFNULL(sum(case when hoding_type = '99' and cdate = STR_TO_DATE(#{cdate},'%Y-%m-%d') then AMOUNT end),0) CASH_FLOW_AMOUNT99 from PTL_CASH_POSITION_FLOW where cdate <= STR_TO_DATE(#{cdate},'%Y-%m-%d')
#{ptlFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id, acct_id, ccy ) t4 on t4.portfolio_id = t.portfolioId and t4.acct_id = t.acctNo and t4.ccy = t.ccy left join ( select portfolio_id, acct_id, ccy, IFNULL(sum(case when hoding_type = 'E01' then AMOUNT end),0) ETR_AMOUNTE01, IFNULL(sum(case when hoding_type = 'E02' then AMOUNT end),0) ETR_AMOUNTE02 from ETR_CASH_POSITION where cdate = STR_TO_DATE(#{cdate},'%Y-%m-%d')
#{etrHodingType,jdbcType=VARCHAR}
group by portfolio_id, acct_id, ccy ) t5 on t5.portfolio_id = t.portfolioId and t5.acct_id = t.acctNo and t5.ccy = t.ccy
) z ) zz ) tt where cashBalance <> 0 or cashAvailable <> 0 or tradeCash <> 0 or desirableCash <> 0 or advanceCash <> 0 or preReductionCash <> 0 order by portfolioId desc,acctNo desc
